def naive_relu(x):
    assert len(x.shape) == 2
    x = x.copy()
    for i in range(x.shape[0]):
        for j in range(x.shape[1]):
            x[i, j] = max(x[i, j], 0)
    return x Returns a new rank-2 tensor in which every negative entry of `x` has been replaced by 0 and every non-negative entry kept. Double loop over all m × n entries; O(m·n) scalar operations executed in the Python interpreter.

def naive_add(x, y):
    assert len(x.shape) == 2
    assert x.shape == y.shape
    x = x.copy()
    for i in range(x.shape[0]):
        for j in range(x.shape[1]):
            x[i, j] += y[i, j]
    return x Returns a new rank-2 tensor whose entry (i, j) is `x[i, j] + y[i, j]`, for two tensors of identical shape. m × n independent scalar additions.

def naive_add_matrix_and_vector(x, y):
    assert len(x.shape) == 2
    assert len(y.shape) == 1
    assert x.shape[1] == y.shape[0]
    x = x.copy()
    for i in range(x.shape[0]):
        for j in range(x.shape[1]):
            x[i, j] += y[j]
    return x Adds a vector `y` to every row of a matrix `x` using explicit Python loops, returning a new matrix. It shows, at the algorithmic level, what NumPy's broadcast addition computes without ever building a repeated copy of `y`. O(n·m) element-wise loop; memory O(n·m) for the copy of `x` plus O(m) for `y` — no O(n·m) copy of `y` is needed.

def naive_matrix_vector_product(x, y):
    assert len(x.shape) == 2
    assert len(y.shape) == 1
    assert x.shape[1] == y.shape[0]
    z = np.zeros(x.shape[0])
    for i in range(x.shape[0]):
        for j in range(x.shape[1]):
            z[i] += x[i, j] * y[j]
    return z Multiplies a matrix x by a vector y, returning a vector with one entry per row of x; each entry is the sum of products of that row with y. O(m·n) multiply-accumulate.

def naive_matrix_vector_product(x, y):
    z = np.zeros(x.shape[0])
    for i in range(x.shape[0]):
        z[i] = naive_vector_product(x[i, :], y)
    return z Same result as c1, but each output coefficient is computed by calling naive_vector_product (p.56) on row i of x and y, making the row-by-row structure explicit. m calls to an O(n) dot product; the shape asserts now happen inside naive_vector_product.

def naive_matrix_product(x, y):
    assert len(x.shape) == 2
    assert len(y.shape) == 2
    assert x.shape[1] == y.shape[0]
    z = np.zeros((x.shape[0], y.shape[1]))
    for i in range(x.shape[0]):
        for j in range(y.shape[1]):
            row_x = x[i, :]
            column_y = y[:, j] Begins the matrix–matrix product: validates shapes, allocates an (x.shape[0], y.shape[1]) result, and loops over every (row of x, column of y) pair, extracting the row and column vectors. The computation of z[i, j] and the return statement are on p.58. m·p vector products of length n: O(m·n·p).

