import keras
from keras import ops

class NaiveDense:
    def __init__(self, input_size, output_size, activation=None):
        self.activation = activation
        self.W = keras.Variable(
            shape=(input_size, output_size), initializer="uniform"
        )
        self.b = keras.Variable(shape=(output_size,), initializer="zeros")

    def __call__(self, inputs):
        x = ops.matmul(inputs, self.W)
        x = x + self.b
        if self.activation is not None:
            x = self.activation(x)
        return x Defines a minimal Dense layer: the constructor creates a randomly initialized weight matrix W and a zero bias b as Keras variables; calling the instance on a batch computes activation(matmul(inputs, W) + b). State creation once, then a three-step forward computation per call.

@property
def weights(self):
    return [self.W, self.b] Completes the NaiveDense class from p.77 with a property returning the layer's two variables. None; accessor.

class NaiveSequential:
    def __init__(self, layers):
        self.layers = layers

    def __call__(self, inputs):
        x = inputs
        for layer in self.layers:
            x = layer(x)
        return x

    @property
    def weights(self):
        weights = []
        for layer in self.layers:
            weights += layer.weights
        return weights Chains a list of layers: calling the model applies each layer in order; the weights property returns the concatenation of all layers' weights. Function composition and list concatenation.

